@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class SmelterProbe {
 public static final BlockPos P=new BlockPos(1920,205,8);static ServerPlayer actor;static int ticks,stage;static long due;static AbstractFurnaceBlockEntity plain,boosted;static int normalBefore,boostBefore;public static volatile boolean ready;static boolean menuOpened;static final UUID OWNER=UUID.fromString("9be50aab-b1ec-4ce3-95b9-833f5d467330");
 static String mode(){return System.getProperty("thaumcraft.alchemyProbe","");}static boolean enabled(){return mode().startsWith("smelters-");}
 static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
 static AlchemyMachine machine(ServerLevel l,BlockPos p,AlchemyBlock block){l.setBlockAndUpdate(p,Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(p,block.defaultBlockState());return (AlchemyMachine)l.getBlockEntity(p);}
 static void load(AlchemyMachine m,AlchemyState state){var l=(ServerLevel)m.getLevel();var tag=m.saveWithoutMetadata(l.registryAccess());tag.put("alchemy",AlchemyState.CODEC.encodeStart(NbtOps.INSTANCE,state).getOrThrow());m.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),tag));m.setChanged();}
 static void tick(AlchemyMachine m,int count){var l=(ServerLevel)m.getLevel();for(int i=0;i<count;i++){((net.minecraft.world.level.storage.ServerLevelData)l.getLevelData()).setGameTime(l.getGameTime()+1);m.serverTick();}}
 static void attach(ServerLevel l,BlockPos p,SmelterUpgradeBlock block,Direction toward){l.setBlockAndUpdate(p,block.defaultBlockState().setValue(SmelterUpgradeBlock.FACING,toward));}
 static int progress(AbstractFurnaceBlockEntity f){return f.saveWithoutMetadata(f.getLevel().registryAccess()).getIntOr("cooking_time_spent",0);}
 static void recipes(ServerPlayer p){var l=p.level();var at=P.offset(0,0,-7);l.setBlockAndUpdate(at,ArcaneContent.WORKBENCH.get().defaultBlockState());l.setBlockAndUpdate(at.above(),ArcaneContent.CHARGER.get().defaultBlockState());var work=(ArcaneWorkbenchEntity)l.getBlockEntity(at);p.setPos(Vec3.atCenterOf(at));KnowledgeStore.write(p,KnowledgeState.EMPTY);
  for(String name:List.of("metal_alchemical","metal_alchemical_advanced","smelter_thaumium","smelter_void","bellows","smelter_aux","smelter_vent")){try(var reader=l.getServer().getResourceManager().openAsReader(SimpleContent.id("recipe/arcane/"+name+".json"))){var root=JsonParser.parseReader(reader).getAsJsonObject();var recipe=root.getAsJsonObject("recipe");work.inventory.clearContent();var rows=recipe.getAsJsonArray("pattern");var keys=recipe.getAsJsonObject("key");for(int y=0;y<rows.size();y++){String row=rows.get(y).getAsString();for(int x=0;x<row.length();x++)if(row.charAt(x)!=' '){String id=keys.get(String.valueOf(row.charAt(x))).getAsString();if(id.startsWith("#"))id="minecraft:oak_planks";work.inventory.setItem(x+y*3,new ItemStack(BuiltInRegistries.ITEM.getValue(net.minecraft.resources.Identifier.parse(id))));}}
   for(var c:root.getAsJsonObject("crystals").entrySet())work.inventory.setItem(9+ArcaneRecipe.PRIMALS.indexOf(c.getKey()),CrystalContent.essence(c.getKey(),c.getValue().getAsInt()));for(var source:work.sources())AuraData.get(l).put(AuraCell.key(source.getX()>>4,source.getZ()>>4),new AuraCell(500,500,0));var match=work.match();check(match!=null&&match.result().is(BuiltInRegistries.ITEM.getValue(SimpleContent.id(name)))&&match.vis()==root.get("vis").getAsInt(),"Native arcane recipe mismatch "+name);int vis=work.availableVis();check(!work.craft(p)&&work.availableVis()==vis&&work.inventory.getItem(15).isEmpty(),"Locked recipe bypassed research "+name);ResearchService.grant(p,root.get("research").getAsString().split("@")[0]);check(work.craft(p)&&vis-work.availableVis()==root.get("vis").getAsInt()&&work.inventory.getItem(15).getCount()==recipe.getAsJsonObject("result").get("count").getAsInt(),"Arcane cost/result failed "+name);for(int slot=0;slot<15;slot++)check(work.inventory.getItem(slot).isEmpty(),"Arcane ingredient/crystal payment wrong "+name+" slot="+slot);KnowledgeStore.write(p,ResearchService.state(p).stage(root.get("research").getAsString().split("@")[0],0));
  }catch(java.io.IOException e){throw new RuntimeException(e);}}
  var state=ResearchService.state(p).stage("TUBES",999).stage("METALLURGY",999).stage("BASEELDRITCH",999).stage("ESSENTIASMELTERTHAUMIUM",1).addPoints("THEORY","ALCHEMY",1000).addPoints("THEORY","ELDRITCH",1000);KnowledgeStore.write(p,state);p.getInventory().add(new ItemStack(SimpleContent.ITEMS.get("plate_thaumium").get()));check(ResearchService.advance(p,"ESSENTIASMELTERTHAUMIUM")&&ResearchService.knows(p,"ESSENTIASMELTERTHAUMIUM"),"Thaumium research native requirements unavailable");KnowledgeStore.write(p,ResearchService.state(p).stage("ESSENTIASMELTERVOID",1));p.getInventory().add(new ItemStack(SimpleContent.ITEMS.get("plate_void").get()));check(ResearchService.advance(p,"ESSENTIASMELTERVOID")&&ResearchService.knows(p,"ESSENTIASMELTERVOID"),"Void research native requirements unavailable");Thaumcraft.LOGGER.info("SMELTERS_RECIPES_OK: seven native arcane crafts, locked refusal, exact aura/crystals and real construct craft proofs unlock both tier researches");
 }
 static void mechanics(ServerPlayer p){var l=p.level();recipes(p);var types=List.of(AlchemyContent.SMELTER.get(),AlchemyContent.THAUMIUM.get(),AlchemyContent.VOID.get());int value=AspectAmounts.total(AspectResolver.item(l,new ItemStack(Items.COAL)));for(int tier=0;tier<3;tier++){var m=machine(l,P.offset(tier*5,0,0),types.get(tier));if(tier==2)for(var d:List.of(Direction.WEST,Direction.EAST,Direction.SOUTH))attach(l,m.getBlockPos().relative(d),AlchemyContent.VENT.get(),d.getOpposite());l.getRandom().setSeed(1347);m.inventory.setItem(0,new ItemStack(Items.COAL,6));m.inventory.setItem(1,new ItemStack(AlchemyContent.ALUMENTUM.get()));tick(m,value*12+10);check(m.inventory.getItem(0).isEmpty()&&m.processed()==value*6&&m.processed()==m.total()+m.polluted()+m.vented(),"Smelting did not conserve aspects for tier "+tier);check(m.speedBoost()&&m.burn()>0,"Alumentum boost missing after consuming last fuel");if(tier<2)check(m.vented()==0,"Unattached vent reduced pollution");else check(m.vented()>0,"Three attached vents failed to remove pollution");Thaumcraft.LOGGER.info("SMELTERS_TIER_{}_OK: processed={} retained={} flux={} vented={}",tier,m.processed(),m.total(),m.polluted(),m.vented());}
  var m=machine(l,P.south(5),AlchemyContent.THAUMIUM.get());int base; m.inventory.setItem(0,new ItemStack(Items.COAL));base=m.needed();for(var d:List.of(Direction.WEST,Direction.EAST,Direction.SOUTH))attach(l,m.getBlockPos().relative(d),AlchemyContent.BELLOWS.get(),d.getOpposite());check(m.bellows()==3&&m.needed()<base,"Three bellows did not accelerate smelter");var blocked=m.getBlockPos().west();l.setBlockAndUpdate(blocked.north(),Blocks.REDSTONE_BLOCK.defaultBlockState());check(m.bellows()==2,"Redstone did not disable bellows");l.removeBlock(blocked.north(),false);attach(l,m.getBlockPos().north(),AlchemyContent.BELLOWS.get(),Direction.SOUTH);check(m.bellows()==3,"Front bellows counted");for(var d:Direction.values()){var at=m.getBlockPos().relative(d);if(l.getBlockState(at).getBlock() instanceof SmelterUpgradeBlock)l.removeBlock(at,false);}m.inventory.clearContent();
  load(m,new AlchemyState(1,Map.of("aer",8),0,0,0,0,0,-100));var columns=new ArrayList<AlchemyMachine>();columns.add(machine(l,m.getBlockPos().above(),AlchemyContent.ALEMBIC.get()));for(var d:List.of(Direction.WEST,Direction.EAST,Direction.SOUTH)){var port=m.getBlockPos().relative(d);attach(l,port,AlchemyContent.AUX.get(),d.getOpposite());columns.add(machine(l,port.above(),AlchemyContent.ALEMBIC.get()));}tick(m,20);check(m.total()==0&&columns.stream().allMatch(a->a.total()==2),"Four independent columns lost or duplicated essence");
  var bufferAt=P.offset(10,0,6);l.setBlockAndUpdate(bufferAt,EssentiaContent.TUBES.get("tube_buffer").get().defaultBlockState());var buffer=(TubeEntity)l.getBlockEntity(bufferAt);attach(l,bufferAt.west(),AlchemyContent.BELLOWS.get(),Direction.EAST);check(buffer.suction(Direction.UP)==32,"Buffer bellows suction wrong");buffer.cycleChoke(Direction.UP);check(buffer.suction(Direction.UP)==1,"Buffer half-choke bypassed");buffer.cycleChoke(Direction.UP);check(buffer.suction(Direction.UP)==0,"Buffer closed choke bypassed");l.setBlockAndUpdate(bufferAt.west(2),Blocks.REDSTONE_BLOCK.defaultBlockState());check(buffer.suction(Direction.NORTH)==1,"Powered bellows still boosting buffer");
  // Placement uses the real item, refuses front/up and accepts a rear mount.
  p.setPos(Vec3.atCenterOf(P));p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AlchemyContent.AUX.get()));var front=new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(P),Direction.NORTH,P,false));check(p.getMainHandItem().getItem().useOn(front)!=InteractionResult.SUCCESS&&p.getMainHandItem().getCount()==1,"Port mounted on furnace front");var rear=new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(P),Direction.SOUTH,P,false));check(p.getMainHandItem().getItem().useOn(rear)==InteractionResult.SUCCESS&&p.getMainHandItem().isEmpty(),"Rear mount failed native placement");
  Thaumcraft.LOGGER.info("SMELTERS_UPGRADES_OK: bellows/front/redstone, four actual alembic columns, buffer suction/chokes and native port placement");
 }
 static void furnaces(ServerLevel l){var a=P.offset(-7,0,10);var b=a.east(4);l.setBlockAndUpdate(a,Blocks.FURNACE.defaultBlockState());l.setBlockAndUpdate(b,Blocks.FURNACE.defaultBlockState());plain=(AbstractFurnaceBlockEntity)l.getBlockEntity(a);boosted=(AbstractFurnaceBlockEntity)l.getBlockEntity(b);for(var f:List.of(plain,boosted)){f.setItem(0,new ItemStack(Items.IRON_ORE,4));f.setItem(1,new ItemStack(Items.COAL));}attach(l,b.west(),AlchemyContent.BELLOWS.get(),Direction.EAST);due=l.getGameTime()+80;stage=2;}
 static void pending(ServerLevel l){var m=machine(l,P.offset(15,0,0),AlchemyContent.VOID.get());m.inventory.setItem(0,new ItemStack(Items.COAL,8));m.inventory.setItem(1,new ItemStack(AlchemyContent.ALUMENTUM.get()));tick(m,10);check(m.burn()==4791&&m.cook()==10&&m.speedBoost(),"Pending fuel setup wrong");}
 static void gallery(ServerPlayer p){var l=p.level();for(var at:BlockPos.betweenClosed(P.offset(-10,0,-8),P.offset(22,7,14)))l.setBlockAndUpdate(at,Blocks.AIR.defaultBlockState());for(int i=0;i<3;i++){var at=P.offset(-5+i*5,0,0);var m=machine(l,at,List.of(AlchemyContent.SMELTER.get(),AlchemyContent.THAUMIUM.get(),AlchemyContent.VOID.get()).get(i));l.setBlockAndUpdate(at,m.getBlockState().setValue(AlchemyBlock.FACING,Direction.SOUTH));m.inventory.setItem(0,new ItemStack(Items.COAL,32));m.inventory.setItem(1,new ItemStack(AlchemyContent.ALUMENTUM.get(),2));machine(l,at.above(),AlchemyContent.ALEMBIC.get());machine(l,at.above(2),AlchemyContent.ALEMBIC.get());if(i==0)attach(l,at.west(),AlchemyContent.BELLOWS.get(),Direction.EAST);if(i==1){attach(l,at.west(),AlchemyContent.BELLOWS.get(),Direction.EAST);attach(l,at.east(),AlchemyContent.AUX.get(),Direction.WEST);machine(l,at.east().above(),AlchemyContent.ALEMBIC.get());}if(i==2)attach(l,at.east(),AlchemyContent.VENT.get(),Direction.WEST);}
  p.teleportTo(l,P.getX()+.5,P.getY(),P.getZ()+9.5,Set.of(),180,4,true);p.resetFallDistance();p.getInventory().clearContent();p.getInventory().setSelectedSlot(0);l.getServer().getCommands().performPrefixedCommand(l.getServer().createCommandSourceStack(),"time set day");ready=true;stage=4;Thaumcraft.LOGGER.info("SMELTERS_CLIENT_OK: real native recipes, all tier conservation, upgrades and vanilla furnace acceleration; active factory ready");
 }
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!enabled()||++ticks<80)return;var l=e.server().overworld();boolean client=!e.server().isDedicatedServer();if(stage==4){if(client&&ready&&!menuOpened&&actor.getInventory().getSelectedSlot()==1){actor.teleportTo(l,P.getX()+.5,P.getY(),P.getZ()+3.5,Set.of(),180,10,true);actor.resetFallDistance();check(((AlchemyMachine)l.getBlockEntity(P)).interact(actor,InteractionHand.MAIN_HAND)==InteractionResult.SUCCESS,"Native smelter menu rejected");menuOpened=true;}return;}
  if(stage==0){if(client){if(e.server().getPlayerList().getPlayers().isEmpty())return;actor=e.server().getPlayerList().getPlayers().getFirst();if(!actor.isAlive())return;}else actor=new ServerPlayer(e.server(),l,new GameProfile(OWNER,"SmelterProbe"),ClientInformation.createDefault()){@Override public void sendSystemMessage(net.minecraft.network.chat.Component c,boolean overlay){} @Override protected ItemCooldowns createItemCooldowns(){return new ItemCooldowns();}};for(int x=119;x<=122;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);stage=1;due=l.getGameTime()+60;if(client){actor.setGameMode(net.minecraft.world.level.GameType.CREATIVE);actor.teleportTo(l,P.getX()+.5,P.getY(),P.getZ()+8.5,Set.of(),180,0,true);}return;}
  if(stage==1&&l.getGameTime()>=due){if(mode().equals("smelters-read")){var m=(AlchemyMachine)l.getBlockEntity(P.offset(15,0,0));check(m!=null&&m.supported()&&m.tier()==2&&m.speedBoost()&&m.burn()>4600&&m.cook()>=0&&m.processed()+m.inventory.getItem(0).getCount()*AspectAmounts.total(AspectResolver.item(l,new ItemStack(Items.COAL)))==8*AspectAmounts.total(AspectResolver.item(l,new ItemStack(Items.COAL))),"Native restart lost pending fuel or items");var old=(AlchemyMachine)l.getBlockEntity(AlchemyProbe.POS);check(old!=null&&old.supported(),"Actual old alchemy save lost");Thaumcraft.LOGGER.info("SMELTERS_RESTART_OK: exact saved pending work, retained alumentum boost and actual pre-upgrade alchemy data");stage=4;e.server().halt(false);return;}for(var at:BlockPos.betweenClosed(P.offset(-10,0,-8),P.offset(22,7,14)))l.setBlockAndUpdate(at,Blocks.AIR.defaultBlockState());for(var at:BlockPos.betweenClosed(P.offset(-10,-1,-8),P.offset(22,-1,14)))l.setBlockAndUpdate(at,Blocks.STONE.defaultBlockState());actor.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);actor.resetFallDistance();actor.setHealth(actor.getMaxHealth());mechanics(actor);if(client){actor.setGameMode(net.minecraft.world.level.GameType.CREATIVE);actor.teleportTo(l,P.getX()+.5,P.getY()+2,P.getZ()+9.5,Set.of(),180,4,true);}furnaces(l);return;}
  if(stage==2&&l.getGameTime()>=due){normalBefore=progress(plain);boostBefore=progress(boosted);check(normalBefore>0&&boostBefore>normalBefore+20&&boosted.getItem(0).getCount()==4&&plain.getItem(0).getCount()==4&&boosted.getItem(2).isEmpty(),"Native bellows did not accelerate cooking or duplicated output");l.setBlockAndUpdate(boosted.getBlockPos().west(2),Blocks.REDSTONE_BLOCK.defaultBlockState());due=l.getGameTime()+30;stage=3;return;}
  if(stage==3&&l.getGameTime()>=due){int a=progress(plain)-normalBefore,b=progress(boosted)-boostBefore;check(a>=29&&b>=29&&Math.abs(a-b)<=2,"Redstone failed to stop native furnace boost");Thaumcraft.LOGGER.info("SMELTERS_VANILLA_OK: real scheduled bellows accelerated vanilla furnace, redstone stopped bonus, input/output conserved");if(client)gallery(actor);else{pending(l);Thaumcraft.LOGGER.info("SMELTERS_WRITE_OK: native mechanics, upgrades, recipes and pending work saved");stage=4;e.server().halt(false);}}
 }
}
